  // Chaque ligne comprend des erreurs expliquées individuellement, jamais
  // une justification automatique fondée seulement sur « réponse incorrecte ».
  function batch(sourceId, concept, extraSources, rows) {
    const theme = sources.find((entry) => entry.id === sourceId).theme;
    rows.forEach((row) => {
      const [id, factId, label, type, prompt, correct, alternatives, explanation, hook] = row;
      const wrong = alternatives.map((entry) => entry[0]);
      const wrongReasons = Object.fromEntries(alternatives);
      const sourceIds = [sourceId].concat(extraSources || []);
      if (wrong.length !== 3 || new Set([correct].concat(wrong)).size !== 4 || alternatives.some((entry) => !entry[1])) {
        throw new Error("QCM incomplet ou ambigu : " + id);
      }
      questions.push({ id, theme, concept, type, official: false, prompt, correct, wrong, explanation, hook, wrongReasons, sourceIds, coverage: [sourceId + ":" + factId] });
      fact(sourceId, factId, label, [id]);
    });
  }

